1	import { Router } from "express";
2	import { z } from "zod";
3	import type { Db } from "@paperclipai/db";
4	import { validate } from "../middleware/validate.js";
5	import { activityService, normalizeActivityLimit } from "../services/activity.js";
6	import { assertAuthenticated, assertBoard, assertCompanyAccess } from "./authz.js";
7	import { heartbeatService, issueService } from "../services/index.js";
8	import { sanitizeRecord } from "../redaction.js";
9	
10	const createActivitySchema = z.object({
11	  actorType: z.enum(["agent", "user", "system", "plugin"]).optional().default("system"),
12	  actorId: z.string().min(1),
13	  action: z.string().min(1),
14	  entityType: z.string().min(1),
15	  entityId: z.string().min(1),
16	  agentId: z.string().uuid().optional().nullable(),
17	  details: z.record(z.unknown()).optional().nullable(),
18	});
19	
20	export function activityRoutes(db: Db) {
21	  const router = Router();
22	  const svc = activityService(db);
23	  const heartbeat = heartbeatService(db);
24	  const issueSvc = issueService(db);
25	
26	  async function resolveIssueByRef(rawId: string) {
27	    if (/^[A-Z]+-\d+$/i.test(rawId)) {
28	      return issueSvc.getByIdentifier(rawId);
29	    }
30	    return issueSvc.getById(rawId);
31	  }
32	
33	  router.get("/companies/:companyId/activity", async (req, res) => {
34	    const companyId = req.params.companyId as string;
35	    assertCompanyAccess(req, companyId);
36	
37	    const filters = {
38	      companyId,
39	      agentId: req.query.agentId as string | undefined,
40	      entityType: req.query.entityType as string | undefined,
41	      entityId: req.query.entityId as string | undefined,
42	      limit: normalizeActivityLimit(Number(req.query.limit)),
43	    };
44	    const result = await svc.list(filters);
45	    res.json(result);
46	  });
47	
48	  router.post("/companies/:companyId/activity", validate(createActivitySchema), async (req, res) => {
49	    assertBoard(req);
50	    const companyId = req.params.companyId as string;
51	    assertCompanyAccess(req, companyId);
52	    const event = await svc.create({
53	      companyId,
54	      ...req.body,
55	      details: req.body.details ? sanitizeRecord(req.body.details) : null,
56	    });
57	    res.status(201).json(event);
58	  });
59	
60	  router.get("/issues/:id/activity", async (req, res) => {
61	    const rawId = req.params.id as string;
62	    const issue = await resolveIssueByRef(rawId);
63	    if (!issue) {
64	      res.status(404).json({ error: "Issue not found" });
65	      return;
66	    }
67	    assertCompanyAccess(req, issue.companyId);
68	    const result = await svc.forIssue(issue.id);
69	    res.json(result);
70	  });
71	
72	  router.get("/issues/:id/runs", async (req, res) => {
73	    const rawId = req.params.id as string;
74	    const issue = await resolveIssueByRef(rawId);
75	    if (!issue) {
76	      res.status(404).json({ error: "Issue not found" });
77	      return;
78	    }
79	    assertCompanyAccess(req, issue.companyId);
80	    const result = await svc.runsForIssue(issue.companyId, issue.id);
81	    res.json(result);
82	  });
83	
84	  router.get("/heartbeat-runs/:runId/issues", async (req, res) => {
85	    assertAuthenticated(req);
86	    const runId = req.params.runId as string;
87	    const run = await heartbeat.getRun(runId);
88	    if (!run) {
89	      res.json([]);
90	      return;
91	    }
92	    assertCompanyAccess(req, run.companyId);
93	    const result = await svc.issuesForRun(runId);
94	    res.json(result);
95	  });
96	
97	  return router;
98	}
